 void persistDraft(){try{collect();if(current!=null)store.draft(current);}catch(Exception e){error(e);}}
 boolean validate(){collect();String name=current.optString("name");if(name.isEmpty()){message("機器名を入力","一覧で見分けられる名前を入力してください。");inputs.get("name").requestFocus();return false;}String mac=current.optString("mac").replace('-',':').toUpperCase(Locale.ROOT);for(String s:mac.split("\\n"))if(!s.trim().isEmpty()&&!Extract.validMac(s.trim())){message("MACアドレスを確認",s+"\nAA:BB:CC:DD:EE:FF の形で入力してください。");return false;}put(current,"mac",mac);for(String ip:current.optString("ip").split("\\n"))if(!ip.isBlank()&&!Extract.validIP(ip.trim())&&!android.util.Patterns.IP_ADDRESS.matcher(ip.trim()).matches()){message("IPアドレスを確認",ip);return false;}String u=current.optString("url");if(!u.isEmpty()){try{java.net.URI uri=new java.net.URI(u);if(!("http".equalsIgnoreCase(uri.getScheme())||"https".equalsIgnoreCase(uri.getScheme()))||uri.getHost()==null||uri.getUserInfo()!=null)throw new Exception();}catch(Exception e){message("管理画面URLを確認","http:// または https:// から入力してください。ID・パスワードはURLに含めず専用欄に入力します。");return false;}}return true;}
