 void choosePhoto(boolean camera){if(photoBusy){message("写真処理中","処理が終わるまでお待ちください。");return;}String[] kinds={"本体","銘板・MAC","設置風景","その他"};new SafeBuilder(this).setTitle("写真の種類").setItems(kinds,(d,n)->{pendingKind=kinds[n];persistDraft();if(camera)capture();else{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,11);}}).show();}
