 void renderPhotos(LinearLayout p,boolean editable){p.removeAllViews();JSONArray a=current.optJSONArray("photos");if(a==null)return;for(int i=0;i<a.length();i++){JSONObject ph=a.optJSONObject(i);final int index=i;LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(0,dp(8),0,dp(12));p.addView(row);ImageView img=new ImageView(this);img.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(img,new LinearLayout.LayoutParams(-1,dp(170)));worker.execute(()->{try{byte[] b=store.photo(ph.getString("file"));BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=3;Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length,opts);runOnUiThread(()->img.setImageBitmap(bmp));}catch(Exception e){runOnUiThread(()->img.setContentDescription("写真を読み込めません"));}});text(row,ph.optString("kind"),13,TEAL,true);img.setOnClickListener(v->viewPhoto(ph));if(editable){button(row,"この写真の文字を読み取る",()->ocr(ph),false);button(row,"この写真を外す",()->new SafeBuilder(this).setMessage("この写真を登録から外しますか？").setPositiveButton("外す",(d,w)->{collect();a.remove(index);persistDraft();renderPhotos(p,true);}).setNegativeButton("戻る",null).show(),false);}}}
