 void importPhotos(ArrayList<Uri> uris){if(current==null){try{current=store.draft();if(current==null)return;if(unlocked)editDevice(current);}catch(Exception e){error(e);return;}}collect();final JSONObject target=current;final String kind=pendingKind;photoBusy=true;Toast.makeText(this,"写真を保存しています…",Toast.LENGTH_SHORT).show();worker.execute(()->{ArrayList<JSONObject> added=new ArrayList<>();try{for(Uri uri:uris){byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){bytes=Store.limited(in,32*1024*1024);}BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);opt.inSampleSize=1;while(Math.max(opt.outWidth,opt.outHeight)/opt.inSampleSize>2400)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;Bitmap bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(bmp==null)throw new Exception("読み込めない画像です");android.media.ExifInterface exif=new android.media.ExifInterface(new ByteArrayInputStream(bytes));int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix mat=new Matrix();switch(orientation){case 2:mat.setScale(-1,1);break;case 3:mat.setRotate(180);break;case 4:mat.setScale(1,-1);break;case 5:mat.setRotate(90);mat.postScale(-1,1);break;case 6:mat.setRotate(90);break;case 7:mat.setRotate(270);mat.postScale(-1,1);break;case 8:mat.setRotate(270);break;}Bitmap rotated=Bitmap.createBitmap(bmp,0,0,bmp.getWidth(),bmp.getHeight(),mat,true);ByteArrayOutputStream out=new ByteArrayOutputStream();rotated.compress(Bitmap.CompressFormat.JPEG,88,out);String id=store.addPhoto(out.toByteArray());added.add(new JSONObject().put("file",id).put("kind",kind));if(rotated!=bmp)rotated.recycle();bmp.recycle();}
 runOnUiThread(()->{for(JSONObject ph:added)target.optJSONArray("photos").put(ph);photoBusy=false;try{store.draft(target);}catch(Exception e){error(e);}if(unlocked&&current==target&&edit){renderPhotos(photoBox,true);if(added.size()==1&&kind.equals("銘板・MAC"))ocr(added.get(0));}Toast.makeText(this,added.size()+" 枚を追加しました",Toast.LENGTH_SHORT).show();});
 }catch(Exception e){runOnUiThread(()->{for(JSONObject ph:added)target.optJSONArray("photos").put(ph);photoBusy=false;try{store.draft(target);}catch(Exception ignored){}if(unlocked&&current==target&&edit)renderPhotos(photoBox,true);error(e);});}finally{if(!pendingCamera.isEmpty()){new File(pendingCamera).delete();pendingCamera="";}}});}
 void ocr(JSONObject ph){if(!edit||photoBusy)return;collect();String targetId=current.optString("id");Toast.makeText(this,"写真の文字を読み取り中…",Toast.LENGTH_SHORT).show();worker.execute(()->{try{byte[] bytes=store.photo(ph.getString("file"));Bitmap bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length);recognizer.process(InputImage.fromBitmap(bmp,0)).addOnSuccessListener(result->{bmp.recycle();if(edit&&current!=null&&current.optString("id").equals(targetId))reviewOcr(result.getText());}).addOnFailureListener(e->{bmp.recycle();error(e);});}catch(Exception e){runOnUiThread(()->error(e));}});}
 void reviewOcr(String raw){if(raw.trim().isEmpty()){message("文字が見つかりません","銘板を明るい場所で大きく写して、撮り直してください。");return;}LinkedHashMap<String,String> found=Extract.fields(raw);ScrollView sv=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(8),dp(18),dp(8));sv.addView(box);text(box,"候補を確認・修正して、反映する項目を選びます。既存の入力は選んだ項目だけ置き換えます。",14,MUTED,false);HashMap<String,EditText> vals=new HashMap<>();HashMap<String,CheckBox> checks=new HashMap<>();for(String[] f:F)if(found.containsKey(f[0])){CheckBox cb=new CheckBox(this);cb.setText(f[1]);cb.setChecked(current.optString(f[0]).isEmpty());box.addView(cb);checks.put(f[0],cb);vals.put(f[0],field(box,"候補",found.get(f[0]),f[0].equals("mac")||f[0].equals("ip")));}if(found.isEmpty())text(box,"自動抽出できる項目がありません。下の読み取り全文から必要な文字を選択してコピーできます。",14,INK,false);text(box,"読み取り全文（長押しで選択・コピー）",13,TEAL,true);TextView t=text(box,raw,15,INK,false);t.setTextIsSelectable(true);CheckBox memo=new CheckBox(this);memo.setText("読み取り全文をメモに追記");box.addView(memo);new SafeBuilder(this).setTitle("読み取り内容の確認").setView(sv).setPositiveButton("選択した項目を反映",(d,w)->{for(String k:checks.keySet())if(checks.get(k).isChecked())inputs.get(k).setText(vals.get(k).getText());if(memo.isChecked()){EditText m=inputs.get("memo");m.setText(m.getText()+"\n[写真から読み取り]\n"+raw);}persistDraft();}).setNegativeButton("反映しない",null).show();}
 void labelPage(){edit=false;screen="label";labelChecks.clear();base("管理ラベル","管理画面URLをQRにして、機器に貼る");LinearLayout preview=card(body);labelPreview=new ImageView(this);labelPreview.setAdjustViewBounds(true);labelPreview.setBackgroundColor(Color.WHITE);preview.addView(labelPreview,new LinearLayout.LayoutParams(-1,dp(145)));text(preview,"プレビュー（テープ幅と項目数に合わせて調整）",12,MUTED,false);LinearLayout options=card(body);Spinner widths=new Spinner(this);widths.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"12 mm","18 mm","24 mm","36 mm"}));widths.setSelection(labelWidth==12?0:labelWidth==18?1:labelWidth==36?3:2);text(options,"テープ幅",14,INK,true);options.addView(widths);widths.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int p,long id){labelWidth=new int[]{12,18,24,36}[p];updateLabel(false);}public void onNothingSelected(AdapterView<?> a){}});text(options,"印刷する項目",18,INK,true);android.content.SharedPreferences prefs=getSharedPreferences("labels",0);for(String[] f:F){CheckBox cb=new CheckBox(this);cb.setText(f[1]+(current.optString(f[0]).isEmpty()?"（未入力）":""));boolean initial=Arrays.asList("name","asset","ip","mac","location").contains(f[0]);cb.setChecked(!current.optString(f[0]).isEmpty()&&prefs.getBoolean(f[0],initial));options.addView(cb);labelChecks.put(f[0],cb);cb.setOnCheckedChangeListener((v,on)->updateLabel(false));}CheckBox qr=new CheckBox(this);qr.setText("管理画面URLのQRコード");qr.setChecked(!current.optString("url").isEmpty());options.addView(qr);labelChecks.put("qr",qr);qr.setOnCheckedChangeListener((v,on)->updateLabel(false));text(options,"QRにはURLのみを入れます。接続先の機器と同じネットワーク等から開いてください。",12,MUTED,false);
 LinearLayout pc=card(body);text(pc,"SR5900Pに印刷",19,INK,true);printerStatus=text(pc,"スマートフォンとプリンターを同じWi-Fiに接続してください。",14,MUTED,false);EditText ip=field(pc,"SR5900PのIPアドレス",prefs.getString("printer_ip",""),false);button(pc,"このIPのプリンターを選択",()->{String s=ip.getText().toString().trim();if(!Extract.validIP(s)){message("IPを確認","SR5900PのIPv4アドレスを入力してください。");return;}selectedPrinter=Printer.manual(s);prefs.edit().putString("printer_ip",s).apply();printerStatus.setText("選択：SR5900P  "+s);},false);button(pc,"Wi-Fi上のSR5900Pを検索",()->{printerStatus.setText("検索中…（20秒）");try{printer.search();handler.postDelayed(()->{printer.stopSearch();if(selectedPrinter==null&&printerStatus!=null)printerStatus.setText("見つからない場合はIPアドレスを指定してください。");},20000);}catch(Exception e){error(e);}},false);button(pc,"ラベルを1枚印刷",()->{if(!updateLabel(true))return;if(selectedPrinter==null){message("プリンターを選択","検索またはIPアドレス入力で選択してください。");return;}boolean sensitive=labelChecks.get("password").isChecked()||labelChecks.get("login").isChecked();new SafeBuilder(this).setTitle("このラベルを印刷しますか？").setMessage(labelWidth+" mm / 1枚"+(sensitive?"\nIDまたはパスワードがラベルに印刷されます。":"")).setPositiveButton("印刷",(d,w)->printer.print(new HashMap<>(selectedPrinter),new ArrayList<>(labelLines),labelUrl,labelWidth)).setNegativeButton("戻る",null).show();},true);button(pc,"印刷を中止",()->printer.cancel(),false);button(body,"ラベル画像をPNGで保存",()->{if(updateLabel(true)){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("image/png");i.putExtra(Intent.EXTRA_TITLE,current.optString("asset","equipment")+"-label.png");startActivityForResult(i,30);}},false);button(body,"機器に戻る",()->detail(current),false);TextView credit=text(body,"Powerted by KING JIM TEPRA-Print SDK",12,MUTED,false);credit.setOnClickListener(v->openUrl("https://www.kingjim.co.jp/download/tepra/sdk/"));updateLabel(false);}
 boolean updateLabel(boolean alert){if(labelPreview==null||labelChecks.isEmpty())return false;labelLines.clear();for(String[] f:F){CheckBox cb=labelChecks.get(f[0]);if(cb!=null&&cb.isChecked()&&!current.optString(f[0]).isEmpty()){String prefix=f[0].equals("name")?"":f[1].replaceAll("（.*?）","")+": ";for(String line:current.optString(f[0]).split("\\n"))if(!line.isBlank())labelLines.add(prefix+line);}}labelUrl=labelChecks.containsKey("qr")&&labelChecks.get("qr").isChecked()?current.optString("url"):"";try{if(labelChecks.containsKey("qr")&&labelChecks.get("qr").isChecked()&&labelUrl.isEmpty())throw new Exception("管理画面URLを登録してからQRを選択してください");int height=labelWidth==12?144:labelWidth==18?216:labelWidth==24?288:384;labelBitmap=Labels.render(labelLines,labelUrl,height,360);labelPreview.setImageBitmap(labelBitmap);labelPreview.setContentDescription("ラベルプレビュー");android.content.SharedPreferences.Editor e=getSharedPreferences("labels",0).edit();for(String k:labelChecks.keySet())if(!k.equals("password")&&!k.equals("login"))e.putBoolean(k,labelChecks.get(k).isChecked());e.apply();return true;}catch(Exception e){labelBitmap=null;labelPreview.setImageDrawable(null);labelPreview.setContentDescription(e.getMessage());if(alert)error(e);else Toast.makeText(this,e.getMessage(),Toast.LENGTH_SHORT).show();return false;}}
 void printerFound(Map<String,String> p){if(!unlocked||!screen.equals("label"))return;String name=p.get(jp.co.kingjim.tepraprint.sdk.TepraPrintDiscoverPrinter.PRINTER_INFO_NAME);new SafeBuilder(this).setTitle("SR5900Pが見つかりました").setMessage(name+"\n"+p.get(jp.co.kingjim.tepraprint.sdk.TepraPrintDiscoverPrinter.PRINTER_INFO_HOST)).setPositiveButton("選択",(d,w)->{selectedPrinter=p;printer.stopSearch();if(printerStatus!=null)printerStatus.setText("選択："+name);}).setNegativeButton("閉じる",null).show();}
 void settings(){screen="settings";edit=false;base("バックアップ・使い方","機器台帳 1.1.0 / Android 11以降");button(body,"Gemini APIキー・モデル設定",()->geminiUi.settings(),true);LinearLayout c=card(body);text(c,"写真・認証情報ごとバックアップ",20,INK,true);text(c,"パスワード付きの .eqbk ファイルに保存します。パスワードを忘れると復元できません。機種変更やアンインストールの前に必ず保存してください。復元は追加方式で、同じデータを再度復元すると重複します。復元ファイルは160MBまで。",14,MUTED,false);button(c,"暗号化バックアップを保存",()->backupDialog(false),true);button(c,"バックアップから追加復元",()->backupDialog(true),false);LinearLayout help=card(body);text(help,"使い方",20,INK,true);text(help,"1. 機器を登録し、本体・銘板・設置風景を撮影。\n2. 銘板写真のOCR候補を確認し、採用する項目にチェック。\n3. 場所・価格・管理画面URLなどを補って保存。\n4. ラベルに載せる項目とテープ幅を選択。\n5. SR5900Pと同じWi-Fiにつなぎ、検索またはプリンターIPを指定して印刷。\n\nQRのリンク先は各機器の管理画面URLです。このアプリの台帳は端末内に保存され、他端末と自動同期しません。\n\n初回の印刷は1枚で位置・文字・QRの読み取りを確認してください。多くの項目を載せるときは24/36mmテープが適します。\n\nOCRは写真内の文字の読み取りです。Geminiでは選択した本体・銘板写真からメーカー・型番の候補を出せます。AIの候補は確認して反映します。場所・価格は写真に明記されたもののみ候補化します。",15,INK,false);text(help,"保護：端末認証 / AES-GCM暗号化 / スクリーンショット抑止 / Android自動バックアップ無効。OCR画像は端末内で処理します。PNGラベルを保存した場合、そのファイルは暗号化されません。",13,MUTED,false);button(body,"一覧に戻る",()->home(),false);}
 void backupDialog(boolean restore){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),dp(8),dp(20),dp(8));EditText p=field(box,restore?"バックアップのパスワード":"新しいバックアップ用パスワード（8文字以上）","",false);p.setInputType(129);EditText confirm=restore?null:field(box,"確認用にもう一度入力","",false);if(confirm!=null)confirm.setInputType(129);AlertDialog d=new SafeBuilder(this).setTitle(restore?"バックアップを復元":"バックアップを保存").setView(box).setPositiveButton("ファイルを選ぶ",null).setNegativeButton("戻る",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String s=p.getText().toString();if(s.length()<8){p.setError("8文字以上で入力してください");return;}if(confirm!=null&&!s.equals(confirm.getText().toString())){confirm.setError("パスワードが一致しません");return;}backupPassword=s.toCharArray();Intent i=new Intent(restore?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);if(!restore)i.putExtra(Intent.EXTRA_TITLE,"equipment-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmm",Locale.JAPAN).format(new Date())+".eqbk");startActivityForResult(i,restore?21:20);d.dismiss();}));d.show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==90){authPending=false;if(result==RESULT_OK){unlocked=true;home();}else showLock();return;}if(result!=RESULT_OK){if(request==10&&!pendingCamera.isEmpty()){new File(pendingCamera).delete();pendingCamera="";}if(request==20||request==21){if(backupPassword!=null)Arrays.fill(backupPassword,'\0');backupPassword=null;}return;}
 if(request==10){if(!pendingCamera.isEmpty()){ArrayList<Uri> list=new ArrayList<>();list.add(Uri.fromFile(new File(pendingCamera)));importPhotos(list);}return;}
 if(request==11&&data!=null){ArrayList<Uri> list=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)list.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)list.add(data.getData());importPhotos(list);return;}
 if(request==30&&data!=null&&data.getData()!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(labelBitmap==null)throw new Exception("もう一度ラベルプレビューを作成してください");labelBitmap.compress(Bitmap.CompressFormat.PNG,100,out);Toast.makeText(this,"ラベル画像を保存しました",Toast.LENGTH_LONG).show();}catch(Exception e){error(e);}return;}
 if((request==20||request==21)&&data!=null&&data.getData()!=null){if(backupPassword==null){message("やり直してください","画面が再作成されたため、パスワードを再入力してください。");return;}final char[] password=backupPassword;backupPassword=null;Uri uri=data.getData();ProgressDialog progress=ProgressDialog.show(this,"処理中",request==20?"バックアップを保存しています…":"バックアップを復元しています…",true,false);worker.execute(()->{try{if(request==20){try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){store.exportBackup(out,password);}runOnUiThread(()->message("保存完了","写真を含む暗号化バックアップを保存しました。"));}else{int n;try(InputStream in=getContentResolver().openInputStream(uri)){n=store.importBackup(in,password);}final int count=n;runOnUiThread(()->{home();message("復元完了",count+" 台の機器を追加しました。");});}}catch(Exception e){runOnUiThread(()->message("処理できませんでした",request==21?"パスワードが違うか、ファイルが破損・非対応です。既存の台帳は保持されています。":"保存に失敗しました。空き容量や保存先を確認してください。"));}finally{Arrays.fill(password,'\0');runOnUiThread(()->progress.dismiss());}});}}
 @Override public void onBackPressed(){if(!unlocked){finish();return;}if(photoBusy){message("写真処理中","写真の保存が終わるまでお待ちください。");return;}if(edit){persistDraft();home();}else if(screen.equals("label"))detail(current);else if(!screen.equals("home"))home();else super.onBackPressed();}
